import { uid } from "@svar-ui/lib-dom";
import type { IGanttTask, IGanttLink, ILink } from "./types";
import { heightAdjustment } from "./tasks";

const delta = 20;

export const updateLink = function (
	link: IGanttLink,
	startTask: IGanttTask,
	endTask: IGanttTask,
	cellHeight: number
): IGanttLink {
	if (
		!startTask ||
		!endTask ||
		!startTask.$y ||
		!endTask.$y ||
		startTask.$skip ||
		endTask.$skip
	) {
		link.$p = "";
		link.$pl = 0;
		link.$x1 = link.$x2 = link.$y1 = link.$y2 = 0;
		return link;
	}

	let s_start = false;
	let e_start = false;

	switch (link.type) {
		case "e2s":
			e_start = true;
			break;

		case "s2s":
			s_start = true;
			e_start = true;
			break;

		case "s2e":
			s_start = true;
			break;

		default:
			break;
	}

	const sx = s_start ? startTask.$x : startTask.$x + startTask.$w;
	const sy = startTask.$y + startTask.$h / 2;
	const ex = e_start ? endTask.$x : endTask.$x + endTask.$w;
	const ey = endTask.$y + endTask.$h / 2;

	const offset = (cellHeight - heightAdjustment - endTask.$h) / 2;

	if (sx !== ex || sy !== ey) {
		const {
			coords: lineCoords,
			pl,
			x1,
			x2,
			y1,
			y2,
		} = getLineCoords(
			sx,
			sy,
			ex,
			ey,
			s_start,
			e_start,
			cellHeight / 2,
			offset
		);

		const arrowCoords = getArrowCoords(ex, ey, e_start);
		link.$p = `${lineCoords},${arrowCoords}`;
		link.$pl = pl;
		link.$x1 = Math.min(x1, ex - 5);
		link.$x2 = Math.max(x2, ex + 5);
		link.$y1 = Math.min(y1, ey - 3);
		link.$y2 = Math.max(y2, ey + 3);
	}

	return link;
};

function getLineCoords(
	sx: number,
	sy: number,
	ex: number,
	ey: number,
	s_start: boolean,
	e_start: boolean,
	gapp: number,
	offset: number
): {
	coords: string;
	pl: number;
	x1: number;
	x2: number;
	y1: number;
	y2: number;
} {
	const shift = delta * (s_start ? -1 : 1);
	const backshift = delta * (e_start ? -1 : 1);

	const sx1 = sx + shift;
	const ex1 = ex + backshift;
	const line = [sx, sy, sx1, sy, 0, 0, 0, 0, ex1, ey, ex, ey];

	const dx = ex1 - sx1;
	let dy = ey - sy;

	const same = e_start === s_start;
	if (!same) {
		if ((ex1 <= sx + delta - 2 && e_start) || (ex1 > sx && !e_start)) {
			dy = dy - gapp + offset;
		}
	}

	if ((same && e_start && sx1 > ex1) || (same && !e_start && sx1 < ex1)) {
		line[4] = line[2] + dx;
		line[5] = line[3];
		line[6] = line[4];
		line[7] = line[5] + dy;
	} else {
		line[4] = line[2];
		line[5] = line[3] + dy;
		line[6] = line[4] + dx;
		line[7] = line[5];
	}

	let x1 = Infinity,
		x2 = -Infinity,
		y1 = Infinity,
		y2 = -Infinity;
	let pl = 0;
	for (let i = 0; i < line.length - 1; i += 2) {
		if (line[i] < x1) x1 = line[i];
		if (line[i] > x2) x2 = line[i];
		if (line[i + 1] < y1) y1 = line[i + 1];
		if (line[i + 1] > y2) y2 = line[i + 1];
		if (i < line.length - 3) {
			pl += Math.hypot(line[i + 2] - line[i], line[i + 3] - line[i + 1]);
		}
	}

	return { coords: line.join(","), pl, x1, x2, y1, y2 };
}

function getArrowCoords(x: number, y: number, start: boolean) {
	if (start) {
		return `${x - 5},${y - 3},${x - 5},${y + 3},${x},${y}`;
	} else {
		return `${x + 5},${y + 3},${x + 5},${y - 3},${x},${y}`;
	}
}

export function placeLink(
	box: { left: number; top: number },
	start: { x: number; y: number },
	end: { x: number; y: number }
): { width: number; height: number; left: number; top: number; p: string } {
	if (start && end) {
		const width = end.x - start.x;
		const height = end.y - start.y;
		const left = (width > 0 ? start.x : end.x) - box.left;
		const top = (height > 0 ? start.y : end.y) - box.top;
		const p = `${width > 0 ? 0 : -width},${height > 0 ? 0 : -height},${
			width > 0 ? width : 0
		},${height > 0 ? height : 0}`;
		return {
			width: Math.abs(width),
			height: Math.abs(height),
			left,
			top,
			p,
		};
	} else {
		return null;
	}
}

export function normalizeLinks(links: ILink[]) {
	return links?.map(link => {
		const id = link.id || uid();
		return { ...link, id };
	});
}
